// The scene images are generated by `npm run build:images` into public/img/maps at these widths.
export const MAP_WIDTHS = [480, 640, 1024, 1600, 2560];

export const CHARACTER_SLUGS = ['waldo', 'woof', 'wenda', 'wizard', 'odlaw'];

// Order of the scenes, also the order of "Next scene".
export const MAP_SLUGS = ['beach', 'ski-slopes', 'moon-base'];

export const MAP_NAMES = { beach: 'Beach', 'ski-slopes': 'Ski Slopes', 'moon-base': 'Moon Base' };

// Hitbox colours used by the calibration tool; one per character.
export const CHARACTER_COLORS = {
  waldo: '#C8102E',
  woof: '#12233F',
  wenda: '#1A7A43',
  wizard: '#A85A00',
  odlaw: '#00708F',
};

export const characterImage = (slug, ext = 'png') => `/img/characters/${slug}.${ext}`;

export function mapSrcSet(slug, format, widths = MAP_WIDTHS) {
  return widths.map((width) => `/img/maps/${slug}-${width}.${format} ${width}w`).join(', ');
}

export const mapPlaceholder = (slug) => `/img/maps/${slug}-placeholder.webp`;

export function nextMapSlug(slug) {
  const index = MAP_SLUGS.indexOf(slug);
  return MAP_SLUGS[(index + 1) % MAP_SLUGS.length];
}

export const mapName = (slug) => MAP_NAMES[slug] ?? slug;

// "Scene 2 · Ski Slopes"
export function sceneLabel(slug) {
  const index = MAP_SLUGS.indexOf(slug);
  return index === -1 ? mapName(slug) : `Scene ${index + 1} · ${mapName(slug)}`;
}

// The global leaderboard names its columns in camelCase (skiSlopes).
export const camelCase = (slug) => slug.replace(/-(\w)/g, (_, letter) => letter.toUpperCase());
